import React, { useEffect, useState } from "react";
import styled from "styled-components";
import liff from "@line/liff";

const Container = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: white;
`;

const { REACT_APP_LIFF_ID } = process.env;

export const LineMiniPage = () => {
  const [profile, setProfile] = useState(null);

  const [idToken, setIdToken] = useState(null);

  const initial = async () => {
    await liff.init({ liffId: REACT_APP_LIFF_ID });
    if (!liff.isLoggedIn()) {
      liff.login();
    }
    const lineUserProfile = await liff.getProfile();
    const lineUserProfileExtra = liff.getDecodedIDToken();
    const payload = {
      lineUserId: lineUserProfile.userId,
      email: lineUserProfileExtra?.email,
      displayName: lineUserProfile.displayName,
      pictureUrl: lineUserProfile.pictureUrl,
    };

    const response = await fetch(
      `https://api-dev.honconnect.co/api/user/login-line`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      },
    );

    console.log("response hon :>> ", response);
  };

  useEffect(() => {
    initial();
  }, []);

  return (
    <Container>
      <p
        style={{
          wordBreak: "break-all",
          whiteSpace: "pre-wrap",
          color: "black",
        }}
      >
        profile : {JSON.stringify(profile)}
      </p>

      <p
        style={{
          marginTop: 10,
          wordBreak: "break-all",
          whiteSpace: "pre-wrap",
          color: "black",
        }}
      >
        extra : {JSON.stringify(idToken)}
      </p>
    </Container>
  );
};
